// ② 启动失败:循环依赖
// ③ 注入失败:NoSuchBeanDefinitionException
//    业务类放在了启动类所在包的「兄弟目录」下

@Service
public class OrderImportService {

    // 注意:外层没标 @Transactional
    public void importAll(List<Order> list) {
        for (Order o : list) {
            this.saveOne(o);      // 走 this,不经过代理
        }
    }

    @Transactional
    public void saveOne(Order o) {
        orderDao.insert(o);       // 写主表
        itemDao.insert(o.items);  // 写明细
    }
}

