// ① 自动配置类:全部逻辑都藏在条件里
@AutoConfiguration                       // 等价于「配置类 + 参与排序」
@ConditionalOnClass(SmsClient.class)     // 依赖没引 → 整段不生效
@ConditionalOnProperty(name = "sms.enabled", havingValue = "true", matchIfMissing = true)
@EnableConfigurationProperties(SmsProperties.class)
public class SmsAutoConfiguration {

    @Bean
    @ConditionalOnMissingBean             // 用户自己定义了同类型 Bean → 我这个不生效
    public SmsClient smsClient(SmsProperties props) {
        return new SmsClient(props.getEndpoint(), props.getAccessKey());
    }
}

// ② 属性类:前缀 + 默认值
@ConfigurationProperties(prefix = "sms")
public class SmsProperties {
    private String endpoint = "https://sms.example.com";
    private String accessKey;
    private int timeoutMillis = 3000;
    // getter / setter 省略
}

