@Configuration
@EnableAsync
public class AsyncConfig implements AsyncConfigurer {

    @Bean("bizExecutor")
    public ThreadPoolTaskExecutor bizExecutor() {
        ThreadPoolTaskExecutor ex = new ThreadPoolTaskExecutor();
        ex.setCorePoolSize(8);
        ex.setMaxPoolSize(16);
        ex.setQueueCapacity(500);
        ex.setKeepAliveSeconds(60);
        ex.setThreadNamePrefix("biz-async-");          // ① 线程名:排查问题的第一手线索
        ex.setRejectedExecutionHandler(new ThreadPoolExecutor.CallerRunsPolicy()); // ② 背压
        ex.setWaitForTasksToCompleteOnShutdown(true);   // ③ 停机不丢任务
        ex.setAwaitTerminationSeconds(30);
        // ④ 把日志上下文传到异步线程
        ex.setTaskDecorator(runnable -> {
            Map<String, String> ctx = MDC.getCopyOfContextMap();
            return () -> {
                if (ctx != null) MDC.setContextMap(ctx);
                try { runnable.run(); } finally { MDC.clear(); }
            };
        });
        ex.initialize();
        return ex;
    }

    @Override
    public Executor getAsyncExecutor() { return bizExecutor(); }

    @Override
    public AsyncUncaughtExceptionHandler getAsyncUncaughtExceptionHandler() {
        // ⑤ 返回值为空的方法,异常在这里收口;默认实现只打日志、极易被忽略
        return (ex, method, params) ->
                log.error("async failed: {}", method.getName(), ex);
    }
}

// 使用:显式指定线程池,不要依赖默认
@Async("bizExecutor")
public CompletableFuture<Order> loadOrder(Long id) {
    return CompletableFuture.completedFuture(orderMapper.selectById(id));
}
